	if len(args) != 2 {
		return shim.Error("Incorrect number of arguments. Expecting 2")
	}

	user := args[0]
	amount, _ := strconv.Atoi(args[1])

	if amount < 0 {
		return shim.Error("Amount can't be negative.")
	}

	// Check if the user exists
	if balanceOf(stub, []string{user}) == nil {
		return shim.Error("User does not exist.")
	}

	// Check if the user has sufficient funds
	balance, _ := strconv.Atoi(string(balanceOf(stub, []string{user})))
	if balance < amount {
		return shim.Error("The withdrawal amount is more than the balance.")
	}

	// Check if the user has the necessary permissions to withdraw funds
	if !hasPermission(stub, user) {
		return shim.Error("User does not have permission to withdraw funds.")
	}

	// Use transactions to ensure atomicity and consistency
	txID := stub.GetTxID()
	tx := stub.GetTransaction(txID)
	if tx == nil {
		return shim.Error("Transaction not found.")
	}

	// Perform the withdrawal within a transaction
